package com.lmspilot.enrollment.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="live_sessions",indexes=@Index(name="idx_live_session_class_time",columnList="class_id,starts_at")) public class LiveSessionEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public UUID classId; @Column(nullable=false) public UUID courseId; @Column(nullable=false,length=220) public String title=""; @Column(length=120) public String provider="EXTERNAL"; @Column(nullable=false,length=2000) public String joinUrl=""; @Column(length=2000) public String hostUrl; @Column(nullable=false) public Instant startsAt; @Column(nullable=false) public Instant endsAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public LiveSessionStatus status=LiveSessionStatus.SCHEDULED; @Column(nullable=false) public UUID createdBy; @Column(nullable=false) public Instant createdAt=Instant.now(); @Column(nullable=false) public Instant updatedAt=Instant.now(); public LiveSessionEntity(){} }
